package mcjty.incontrol.areas;

import java.util.HashMap;
import java.util.Map;
import javax.annotation.Nullable;
import mcjty.incontrol.areas.Area;
import mcjty.incontrol.areas.AreaParser;
import net.minecraft.world.level.LevelAccessor;

public class AreaSystem {
    private static final Map<String, Area> areas = new HashMap<String, Area>();

    public static void addArea(Area area) {
        areas.put(area.name(), area);
    }

    public static void reloadRules() {
        areas.clear();
        AreaParser.readRules("areas.json");
    }

    @Nullable
    public static String isInArea(LevelAccessor level, int x, int y, int z) {
        for (Area area : areas.values()) {
            if (!area.isInArea(x, y, z)) continue;
            return area.name();
        }
        return null;
    }

    public static Area getArea(String name) {
        return areas.get(name);
    }
}

